create or replace function private.record_audit_export_attempt(p_school_id uuid,p_format text,p_record_count integer,p_filters jsonb,p_success boolean) returns void language plpgsql security definer set search_path = '' as $$ declare v_actor uuid := auth.uid(); begin if v_actor is null then raise exception 'Authentication required'; end if; if not exists(select 1 from public.profiles p where p.id=v_actor and p.is_active=true) then raise exception 'Active account required'; end if; if p_format not in ('csv','pdf','xlsx') then raise exception 'Unsupported export format'; end if; if not private.is_platform_admin() then if p_school_id is null or not private.has_school_role(p_school_id,array['school_admin'::public.membership_role]) then raise exception 'Not authorised to export this school activity'; end if; end if; insert into public.audit_logs(school_id,actor_user_id,action,entity_type,metadata) values(p_school_id,v_actor,case when p_success then 'activity.exported' else 'activity.export_failed' end,'audit_report',jsonb_build_object('format',p_format,'record_count',greatest(coalesce(p_record_count,0),0),'filters',coalesce(p_filters,'{}'::jsonb))); end; $$; revoke all on function private.record_audit_export_attempt(uuid,text,integer,jsonb,boolean) from public,anon,authenticated; create or replace function public.record_audit_export_attempt(p_school_id uuid,p_format text,p_record_count integer,p_filters jsonb,p_success boolean) returns void language sql security invoker set search_path = '' as $$ select private.record_audit_export_attempt(p_school_id,p_format,p_record_count,p_filters,p_success); $$; revoke all on function public.record_audit_export_attempt(uuid,text,integer,jsonb,boolean) from public,anon; grant execute on function public.record_audit_export_attempt(uuid,text,integer,jsonb,boolean) to authenticated;